using System;using UnityEngine;using UnityEngine.UI;
// Global exchange policy belongs to the native World Laws scroll content.
public static class NativeWorldRate {
 public static void Attach(WorldLawsWindow window){try{if(window==null)return;ScrollRect chosen=null;foreach(var scroll in window.GetComponentsInChildren<ScrollRect>(true)){if(scroll.content==null)continue;if(chosen==null)chosen=scroll;if(scroll.gameObject.activeInHierarchy){chosen=scroll;break;}}if(chosen==null||chosen.content==null){Debug.LogWarning("GodWorld: World Laws scroll content missing");return;}var existing=chosen.content.Find("godworld_world_exchange_rate");if(existing!=null){existing.gameObject.SetActive(true);return;}
  var go=new GameObject("godworld_world_exchange_rate",typeof(RectTransform));go.SetActive(false);go.transform.SetParent(chosen.content,false);go.transform.SetAsFirstSibling();NativeCurrencyControls.Fit(go.transform,chosen.content);var layout=go.AddComponent<VerticalLayoutGroup>();layout.childControlWidth=true;layout.childControlHeight=true;layout.childForceExpandWidth=true;layout.childForceExpandHeight=false;layout.spacing=1;var size=go.AddComponent<LayoutElement>();size.minHeight=59;size.preferredHeight=59;go.AddComponent<GodWorldRatePanel>();go.SetActive(true);
 }catch(Exception e){Debug.LogWarning("GodWorld world exchange law: "+e);}}
}
public sealed class GodWorldRatePanel:MonoBehaviour {
 InputField input;KeyValueField current,message;
 KeyValueField Row(string label,string value,Action action=null){var prefab=Resources.Load<GameObject>("ui/KeyValueFieldStats");if(prefab==null)throw new Exception("Native world law row missing");var go=UnityEngine.Object.Instantiate(prefab,transform,false);var row=go.GetComponent<KeyValueField>();row.name_text.text=label;row.value.text=value;if(row.icon!=null)row.icon.gameObject.SetActive(false);var size=go.GetComponent<LayoutElement>()??go.AddComponent<LayoutElement>();size.minHeight=14;size.preferredHeight=14;foreach(var text in new[]{row.name_text,row.value}){text.supportRichText=false;text.resizeTextForBestFit=true;text.resizeTextMinSize=6;text.resizeTextMaxSize=8;text.horizontalOverflow=HorizontalWrapMode.Wrap;text.verticalOverflow=VerticalWrapMode.Truncate;}NativeEconomyUI.BindAction(row,action==null?null:(UnityEngine.Events.UnityAction)(()=>action()));go.SetActive(true);return row;}
 void OnEnable(){try{if(input==null){current=Row("世界汇率","");var row=Row("1 GOD 等于多少金币","");input=NativeCurrencyControls.Input(row,"",false);Row("保存世界汇率","应用 ▸",Save);message=Row("适用范围","全世界，随世界存档保存");}input.SetTextWithoutNotify(GodWorldRuntime.GetRate().ToString("R",System.Globalization.CultureInfo.InvariantCulture));Show();}catch(Exception e){Debug.LogWarning("GodWorld exchange law UI: "+e);}}
 void Show(){if(current!=null)current.value.text="1 GOD = "+GodWorldRuntime.GetRate().ToString("G12",System.Globalization.CultureInfo.InvariantCulture)+" 金币";}
 void Save(){double n;if(!CurrencyInput.TryRate(input.text,out n)){message.value.text="请输入大于0的有效汇率";return;}GodWorldRuntime.SetRate(n);GodWorldRuntime.Flush();message.value.text="已应用；现有余额不变";Show();}
}
